#!/usr/bin/env node
/**
 * Generates a slim per-exercise enrichment mirror for the Worker's AI prompts
 * (Workout Engine v2, Phase 6A).
 *
 * The client has a full 1,552-row canonical catalog
 * (src/data/exerciseCatalog.generated.ts, generated by
 * scripts/generate-exercise-catalog.mjs) carrying movementPattern,
 * loadingType, contraindications, etc. The Worker is a SEPARATE deployable
 * unit with its own vendored copy of the 1,500-exercise ExerciseDB source
 * (fitai-workers/src/data/exerciseDatabase.json) — same exerciseId hash space
 * as the client's, but no dependency on the client's generated file (which
 * may not exist/be in sync at Worker build time). This script re-derives
 * the SAME classification directly from the Worker's own source data, so the
 * Worker's prompt-building code never depends on the client repo state.
 *
 * NOTE — keep in sync: the classification heuristics below (movement
 * pattern/loading type/contraindications keyword vocab) are a deliberate,
 * minimal PORT of scripts/generate-exercise-catalog.mjs's logic (client
 * repo). If that vocab changes, mirror the change here too — there is no
 * shared module between the two deployable units today.
 *
 * Output: fitai-workers/src/data/exerciseEnrichment.json
 *   { [exerciseId]: { movementPattern, loadingType, primaryMuscles[],
 *                      isBodyweight, isTimeBased, contraindications[] } }
 *
 * Usage: node scripts/generate-exercise-enrichment.mjs
 */
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const ROOT = path.resolve(__dirname, "..");

const dbRaw = JSON.parse(
  fs.readFileSync(path.join(ROOT, "src/data/exerciseDatabase.json"), "utf8"),
);
const DB_EXERCISES = dbRaw.exercises;

// ── Vocab (ported from src/data/exerciseClassificationVocab.json, client repo) ──
const LOWER_BODY_GROUPS = new Set(["quadriceps", "hamstrings", "glutes", "calves"]);
const TIME_BASED_KEYWORDS = [
  "plank", "wall sit", "dead hang", "hollow body", "l-sit", "l sit",
  "hold", "superman", "flexed arm hang", "isometric",
];
const DB_MUSCLE_TO_GROUP = {
  chest: "chest", pectorals: "chest", "upper chest": "chest",
  back: "back", lats: "back", "latissimus dorsi": "back", "upper back": "back",
  "lower back": "back", traps: "back", trapezius: "back", rhomboids: "back", spine: "back",
  shoulders: "shoulders", delts: "shoulders", deltoids: "shoulders", "rear deltoids": "shoulders",
  biceps: "biceps", brachialis: "biceps",
  triceps: "triceps",
  quads: "quadriceps", quadriceps: "quadriceps",
  hamstrings: "hamstrings",
  glutes: "glutes",
  calves: "calves", soleus: "calves",
  adductors: "quadriceps", abductors: "glutes", "hip flexors": "quadriceps",
  core: "core", abs: "core", abdominals: "core", "lower abs": "core", obliques: "core",
  "cardiovascular system": "cardio",
};
const LOADING_TYPE_BY_EQUIPMENT = {
  barbell: "barbell", "ez barbell": "barbell", "olympic barbell": "barbell",
  "trap bar": "barbell", "smith machine": "barbell",
  dumbbell: "dumbbell", kettlebell: "dumbbell", hammer: "dumbbell",
  cable: "cable", rope: "cable",
  "leverage machine": "machine", "sled machine": "machine", "stepmill machine": "machine",
  "skierg machine": "machine", "elliptical machine": "machine", "stationary bike": "machine",
  "upper body ergometer": "machine", tire: "machine",
  "body weight": "bodyweight", assisted: "bodyweight", "wheel roller": "bodyweight",
  roller: "bodyweight", "stability ball": "bodyweight", "bosu ball": "bodyweight",
  "medicine ball": "bodyweight", weighted: "bodyweight",
  band: "banded", "resistance band": "banded",
};
const MOVEMENT_PATTERN_PRIORITY = [
  "squat", "hinge", "lunge", "carry", "rotation",
  "vertical_pull", "horizontal_pull", "vertical_push", "horizontal_push",
];
const MOVEMENT_PATTERN_KEYWORDS = {
  squat: ["squat"],
  hinge: ["deadlift", "hip thrust", "good morning", "romanian"],
  lunge: ["lunge", "split squat", "step up", "step-up", "step through"],
  carry: ["carry", "farmer", "suitcase walk", "waiters walk", "yoke walk"],
  rotation: ["twist", "rotation", "wood chop", "woodchop", "chop", "oblique"],
  vertical_pull: ["pulldown", "pull up", "pull-up", "pullup", "chin up", "chin-up", "chinup"],
  horizontal_pull: ["row"],
  vertical_push: ["overhead press", "shoulder press", "military press", "push press", "handstand"],
  horizontal_push: ["bench press", "push up", "push-up", "pushup", "chest press", "fly", "flye", "dip"],
};

function normalize(s) {
  return s.trim().toLowerCase();
}

function mapMuscles(muscles) {
  const groups = new Set();
  for (const m of muscles) {
    const group = DB_MUSCLE_TO_GROUP[normalize(m)];
    if (group && group !== "cardio") groups.add(group);
  }
  return [...groups];
}

function detectMovementPattern(name) {
  const n = normalize(name);
  for (const pattern of MOVEMENT_PATTERN_PRIORITY) {
    const keywords = MOVEMENT_PATTERN_KEYWORDS[pattern] ?? [];
    if (keywords.some((k) => n.includes(k))) return pattern;
  }
  return "isolation";
}

function detectLoadingType(equipment) {
  const primary = normalize(equipment[0] ?? "body weight");
  return LOADING_TYPE_BY_EQUIPMENT[primary] ?? "bodyweight";
}

function detectContraindications(movementPattern, loadingType) {
  const flags = [];
  if (movementPattern === "hinge" && ["barbell", "machine"].includes(loadingType)) {
    flags.push("lower_back");
  }
  if (movementPattern === "vertical_push" && loadingType === "barbell") {
    flags.push("shoulder");
  }
  return flags;
}

const enrichment = {};
for (const ex of DB_EXERCISES) {
  const primaryMuscles = mapMuscles(ex.targetMuscles);
  const isBodyweight = ex.equipments.some((e) => normalize(e) === "body weight");
  const isTimeBased = TIME_BASED_KEYWORDS.some((k) => normalize(ex.name).includes(k));
  const movementPattern = detectMovementPattern(ex.name);
  const loadingType = detectLoadingType(ex.equipments);

  enrichment[ex.exerciseId] = {
    movementPattern,
    loadingType,
    primaryMuscles,
    isBodyweight,
    isTimeBased,
    contraindications: detectContraindications(movementPattern, loadingType),
  };
}

const outPath = path.join(ROOT, "src/data/exerciseEnrichment.json");
fs.writeFileSync(outPath, JSON.stringify(enrichment), "utf8");
console.log(`Wrote ${outPath} (${Object.keys(enrichment).length} entries)`);
